INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q16640433', 'Kongo-Wara rebellion', 'The Kongo-Wara rebellion, also known as the War of the Hoe Handle and the Baya War, was a rural, anticolonial rebellion in the former colonies of French Equatorial Africa and French Cameroon which began as a result of recruitment of the native population in railway construction and rubber tapping. It was a large colonial uprising but also among the least well-known uprisings during the interwar period.', 1928, NULL, NULL, 1931, NULL, NULL, 'year', '1928–1931', 34, 'https://en.wikipedia.org/wiki/Kongo-Wara_rebellion'),
  ('Q781029', 'Saint-Sylvestre coup d''état', 'The Saint-Sylvestre coup d''état was a coup d''état staged by Jean-Bédel Bokassa, commander-in-chief of the Central African Republic (CAR) army, and his officers against the government of President David Dacko on 31 December 1965 and 1 January 1966. Dacko, Bokassa''s cousin, took over the country in 1960, and Bokassa, an officer in the French army, joined the CAR army in 1962.', 1965, 12, 31, 1966, 1, 1, 'day', '31 December 1965 – 1 January 1966', 43, 'https://en.wikipedia.org/wiki/Saint-Sylvestre_coup_d''%C3%A9tat'),
  ('Q20982123', '1981 Central African Republic coup d''état', 'On 1 September 1981, General André Kolingba deposed President David Dacko of the Central African Republic in a bloodless coup while Dacko was away from the country traveling to an official state visit in Libya. The day after the coup a "Military Committee for National Recovery" (French: Comite Militaire pour le Redressement National, CMRN) was established and was led by Kolingba.', 1981, 9, 1, NULL, NULL, NULL, 'day', '1 September 1981', 34, 'https://en.wikipedia.org/wiki/1981_Central_African_Republic_coup_d''%C3%A9tat'),
  ('Q303801', 'Lord''s Resistance Army insurgency', 'The Lord''s Resistance Army insurgency is an ongoing conflict between the Lord''s Resistance Army (LRA), a Ugandan militant religious extremist group, against the government of Uganda. Following the Ugandan Civil War, militant Joseph Kony formed the Lord''s Resistance Army and launched an insurgency against the newly installed President Yoweri Museveni.', 1987, NULL, NULL, NULL, NULL, NULL, 'year', '1987', 52, 'https://en.wikipedia.org/wiki/Lord''s_Resistance_Army_insurgency'),
  ('Q17512048', '2003 Central African Republic coup d''état', 'A coup d''état occurred in March 2003 in the Central African Republic when the forces of General François Bozizé marched on Bangui, the country''s capital, while President Ange-Félix Patassé was attending a regional Community of Sahel–Saharan States leaders'' summit in Niger.', 2003, 3, NULL, NULL, NULL, NULL, 'month', 'March 2003', 37, 'https://en.wikipedia.org/wiki/2003_Central_African_Republic_coup_d''%C3%A9tat'),
  ('Q3118963', 'Central African Republic Bush War', 'The Central African Bush War was a civil war in the Central African Republic which lasted from 2004 to 2007 between Union of Democratic Forces for Unity (UFDR) rebels and government forces. The rebellion began after François Bozizé seized the nation''s presidency in 2003.', 2004, 11, 23, 2007, NULL, NULL, 'day', '23 November 2004 – 2007', 55, 'https://en.wikipedia.org/wiki/Central_African_Bush_War'),
  ('Q3411181', 'Central African Republic Civil War', 'The Central African Republic Civil War is an ongoing civil war in the Central African Republic (CAR) involving the successive governments, rebels from the former Séléka coalition, the Anti-balaka militias, and various foreign and international forces. In the preceding Central African Bush War (2004–2007), the government of President François Bozizé fought with rebel groups until a peace agreement was signed in 2007.', 2012, 12, 10, 2013, 3, NULL, 'day', '10 December 2012 – March 2013', 64, 'https://en.wikipedia.org/wiki/Central_African_Republic_Civil_War'),
  ('Q15278872', 'Battle of Bangui', 'The Battle of Bangui occurred in March 2013, during the ongoing Central African Republic Civil War, and resulted in Séléka taking power in the Central African Republic. With the Central African Armed Forces and international soldiers absent, most of the resistance was raised by South African soldiers.', 2013, 3, 24, NULL, NULL, NULL, 'day', '24 March 2013', 30, 'https://en.wikipedia.org/wiki/Battle_of_Bangui_(2013)'),
  ('Q15287550', 'Central African Republic conflict under the Djotodia administration', 'An internal conflict in the Central African Republic (CAR) started essentially on 13 April 2013, when the government of President Michel Djotodia officially took over. The fighting was between the government of the Central African Republic''s former Séléka coalition of rebel groups, who are mainly from the Muslim minority, and the mainly Christian anti-balaka coalition.', 2014, 1, 10, 2014, 1, 10, 'day', '10 January 2014', 37, 'https://en.wikipedia.org/wiki/Central_African_Republic_conflict_(2013%E2%80%932014)'),
  ('Q108495378', 'Battle of Bangui', 'On 13 January 2021, during the ongoing civil war in the Central African Republic, around 200 rebels from the Coalition of Patriots for Change attacked the capital Bangui in an attempt to overthrow the government, which resulted in failure.', 2021, 1, 13, NULL, NULL, NULL, 'day', '13 January 2021', 34, 'https://en.wikipedia.org/wiki/Battle_of_Bangui_(2021)'),
  ('Q110714848', 'Aïgbado massacre', 'On 16 and 17 January 2022, at least 65 civilians were killed by Russian mercenaries from the Wagner Group who were supported by armed forces in the villages of Aïgbado and Yanga near Bria in the Central African Republic during an operation against rebels from the Coalition of Patriots for Change.', 2022, 1, 16, 2022, 1, 17, 'day', '16 January 2022 – 17 January 2022', 37, 'https://en.wikipedia.org/wiki/A%C3%AFgbado_massacre');

